    /**
     * Method to retrieve the Security via SecurityFetchOneSummary
     * @param 	summary SecurityFetchOneSummary 
     * @return 	SecurityFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Security getSecurity( SecurityFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "SecurityFetchOneSummary arg cannot be null" );
    	
    	Security entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Security
        	// --------------------------------------
        	CompletableFuture<Security> futureEntity = queryGateway.query(new FindSecurityQuery( new LoadSecurityFilter( summary.getSecurityId() ) ), ResponseTypes.instanceOf(Security.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Security with id " + summary.getSecurityId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


